<div x-show="viewerOpen" x-cloak x-trap.noscroll.noreturn="viewerOpen" role="dialog" aria-modal="true" aria-labelledby="wound-photo-title" class="rm-wound__viewer" @click.self="closeGallery()">
    <div class="rm-wound__viewer-panel"><header><h3 id="wound-photo-title" class="rm-section-title">Fotografía clínica</h3><button x-ref="viewerClose" type="button" class="rm-btn-secondary" @click="closeGallery()">Cerrar fotografía</button></header>
        <template x-if="gallery[current]"><figure><img :src="gallery[current].url" :alt="'Fotografía clínica de herida, ' + gallery[current].fecha"><figcaption><p x-text="gallery[current].ubicacion"></p><p x-text="gallery[current].fecha + ' · ' + gallery[current].profesional"></p><p x-text="gallery[current].descripcion"></p><p x-text="gallery[current].dimensiones"></p><a :href="gallery[current].url + '?descargar=1'" class="rm-btn-secondary">Descargar fotografía</a></figcaption></figure></template>
        <nav aria-label="Navegación de fotografías"><button type="button" class="rm-btn-secondary" @click="step(-1)" :disabled="gallery.length < 2">Anterior</button><span x-text="(current + 1) + ' de ' + gallery.length"></span><button type="button" class="rm-btn-secondary" @click="step(1)" :disabled="gallery.length < 2">Siguiente</button></nav>
    </div>
</div>
<div x-show="compareOpen" x-cloak x-trap.noscroll.noreturn="compareOpen" role="dialog" aria-modal="true" aria-labelledby="wound-compare-title" class="rm-wound__viewer" @click.self="closeGallery()">
    <div class="rm-wound__viewer-panel"><header><h3 id="wound-compare-title" class="rm-section-title">Comparar fotografías</h3><button x-ref="compareClose" type="button" class="rm-btn-secondary" @click="closeGallery()">Cerrar comparación</button></header><p>Comparación visual del historial. No genera una interpretación clínica automática.</p><div class="rm-wound__comparison">
        <template x-for="side in ['before', 'after']" :key="side"><section><label :for="'compare-' + side" x-text="side === 'before' ? 'Antes' : 'Después'"></label><select :id="'compare-' + side" class="rm-select" :value="side === 'before' ? before : after" @change="side === 'before' ? before = Number($event.target.value) : after = Number($event.target.value)"><template x-for="(photo, index) in gallery" :key="photo.codigo"><option :value="index" x-text="photo.fecha + ' · ' + photo.grupo"></option></template></select><template x-if="gallery[side === 'before' ? before : after]"><figure><img :src="gallery[side === 'before' ? before : after].url" :alt="'Fotografía clínica de herida, ' + gallery[side === 'before' ? before : after].fecha"><figcaption><p x-text="gallery[side === 'before' ? before : after].fecha"></p><p x-text="gallery[side === 'before' ? before : after].dimensiones"></p><p x-text="gallery[side === 'before' ? before : after].profesional"></p></figcaption></figure></template></section></template>
    </div></div>
</div>
